<#
  Fix-GPSFirstFixAndProgressFeedback.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  Full, backed-up REPLACEMENT of the 5 files below - same approach as the
  previous Fix-*.ps1 scripts. Each file's exact new content is embedded as
  base64 of the RAW FILE BYTES (BOM preserved where the original file had
  one) and written back byte-for-byte with no text re-encoding step.

  ROOT CAUSE (this was never a "budget phones are slow" problem):

  1. Every "Use My Location" call forced a cold, high-accuracy-only GPS fix
     (enableHighAccuracy:true, maximumAge:0) with no way to reuse a recent
     fix or paint anything before the final lock.
  2. getReliableLocation() already computed live status text ("Getting GPS
     location...", "Precision Lock: +/-40m") but NONE of the screens that
     call it wired up the onProgress callback - vendors/riders just saw a
     blank spinner for up to 32 seconds on a slow connection.
  3. A "good enough" (25-60m) reading always required a second confirming
     ping, even when the first reading arrived slowly (the normal case on
     budget Android here) rather than only when it looked like a
     suspicious cold-start "quick fix" (<2s).
  4. Reverse-geocoding only ran after final GPS lock, adding a second
     network round-trip on top instead of resolving an address the moment
     any usable coordinate existed.

  WHAT CHANGED:

  - src/utils/geolocation.js: onProgress now receives a second argument,
    (message, reading) - existing callers that only read the message are
    unaffected. A parallel low-accuracy, short-timeout getCurrentPosition
    call now feeds onProgress an approximate reading in ~1-3s (never used
    as the resolved answer - still real device positioning, never the
    removed IP fallback). The second-ping requirement is now conditional:
    it only applies when the FIRST ping arrived suspiciously fast (<2s),
    the actual fingerprint of a cold-start "quick fix" - not unconditionally.
  - src/components/MapModal.jsx: "Use My Location" now shows live status
    text in the pin pill, moves the marker on every improving reading, and
    reverse-geocodes on the first fix + final result only (not every ping).
  - src/app/send-package/step-1/page.jsx: same live-status + early
    pan-and-geocode treatment for the pickup GPS button.
  - src/app/vendor/create-delivery/page.jsx: live status text on both Pin
    buttons. Deliberately does NOT try to live-refine the pin inside
    MapModal here, since MapModal only reads its initialLocation prop once
    at mount - updating it mid-flight wouldn't move an already-open modal.
  - src/app/rider/(main)/dashboard/page.jsx: live status text next to the
    Go Online button during GPS lock.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-GPSFirstFixAndProgressFeedback.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-gpsprogress"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FullFile($relPath, $base64Content, $label) {
    $full = Get-FullPath $relPath
    if (-not (Test-Path -LiteralPath $full)) {
        Write-Host "  SKIP (not found): $relPath - is this the right repo root?" -ForegroundColor Yellow
        return
    }
    Backup-Path $full
    $bytes = [System.Convert]::FromBase64String($base64Content)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  REPLACED: $label" -ForegroundColor Green
}

if (-not (Test-Path -LiteralPath (Get-FullPath "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

Write-Host "`nApplying GPS first-fix + live progress-feedback fixes:" -ForegroundColor Cyan

